from __future__ import annotations

from minidb.types import (
    COMPARISON_OPS,
    And,
    ColumnDef,
    ColumnRef,
    ColumnType,
    Comparison,
    CreateTableStmt,
    DeleteStmt,
    DropTableStmt,
    Expr,
    InsertStmt,
    IsNull,
    Literal,
    Not,
    Or,
    SelectStmt,
    SQLSyntaxError,
    Statement,
    Token,
    TokenType,
    Value,
)

__all__ = ["parse", "parse_script", "parse_expression"]


def parse(tokens: list[Token]) -> Statement:
    """Parse exactly one statement, optionally followed by a single ';',
    then EOF.

    Raises:
        SQLSyntaxError: if the tokens are not exactly one valid statement
            (including empty input, a lone ';', or trailing tokens).
    """
    if not tokens:
        raise SQLSyntaxError("Unexpected EOF")

    def _parse_statement(tokens: list[Token]) -> Statement:
        if tokens[0].type == TokenType.KEYWORD and tokens[0].value == "CREATE":
            return _parse_create_table(tokens)
        elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "DROP":
            return _parse_drop_table(tokens)
        elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "INSERT":
            return _parse_insert(tokens)
        elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "SELECT":
            return _parse_select(tokens)
        elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "DELETE":
            return _parse_delete(tokens)
        else:
            raise SQLSyntaxError(f"Unknown statement type: {tokens[0].value}")

    def _parse_create_table(tokens: list[Token]) -> CreateTableStmt:
        if len(tokens) < 6 or tokens[0].value != "CREATE" or tokens[1].value != "TABLE":
            raise SQLSyntaxError("Malformed CREATE TABLE statement")
        table_name = tokens[2].value
        if tokens[3].value != "(":
            raise SQLSyntaxError("Expected '(' after table name")
        columns = []
        i = 4
        while i < len(tokens):
            if tokens[i].type != TokenType.IDENTIFIER:
                raise SQLSyntaxError("Expected column name")
            column_name = tokens[i].value
            i += 1
            if i >= len(tokens) or tokens[i].type != TokenType.KEYWORD:
                raise SQLSyntaxError("Expected column type")
            column_type = tokens[i].value
            if column_type not in {"INTEGER", "TEXT", "BOOLEAN"}:
                raise SQLSyntaxError("Invalid column type")
            columns.append(ColumnDef(column_name, ColumnType[column_type]))
            i += 1
            if i >= len(tokens):
                raise SQLSyntaxError("Expected ',' or ')' after column definition")
            if tokens[i].value == ")":
                break
            elif tokens[i].value == ",":
                i += 1
            else:
                raise SQLSyntaxError("Expected ',' or ')' after column definition")
        if tokens[i].value != ")":
            raise SQLSyntaxError("Expected ')' after column definitions")
        i += 1
        if i != len(tokens) - 1:
            raise SQLSyntaxError("Trailing tokens after CREATE TABLE statement")
        return CreateTableStmt(table_name, tuple(columns))

    def _parse_drop_table(tokens: list[Token]) -> DropTableStmt:
        if len(tokens) < 4 or tokens[0].value != "DROP" or tokens[1].value != "TABLE":
            raise SQLSyntaxError("Malformed DROP TABLE statement")
        table_name = tokens[2].value
        if tokens[3].value != ";" and tokens[3].type != TokenType.EOF:
            raise SQLSyntaxError("Trailing tokens after DROP TABLE statement")
        return DropTableStmt(table_name)

    def _parse_insert(tokens: list[Token]) -> InsertStmt:
        if len(tokens) < 5 or tokens[0].value != "INSERT" or tokens[1].value != "INTO":
            raise SQLSyntaxError("Malformed INSERT statement")
        table_name = tokens[2].value
        columns = None
        i = 3
        if tokens[i].value == "(":
            columns = []
            i += 1
            while i < len(tokens):
                if tokens[i].type != TokenType.IDENTIFIER:
                    raise SQLSyntaxError("Expected column name")
                columns.append(tokens[i].value)
                i += 1
                if i >= len(tokens) or tokens[i].value != ")":
                    raise SQLSyntaxError("Expected ',' or ')' after column name")
                i += 1
                if i >= len(tokens) or tokens[i].value != "VALUES":
                    raise SQLSyntaxError("Expected 'VALUES' after column list")
                i += 1
        elif tokens[i].value == "VALUES":
            i += 1
        else:
            raise SQLSyntaxError("Expected '(' or 'VALUES' after table name")
        if tokens[i].value != "(":
            raise SQLSyntaxError("Expected '(' after VALUES")
        i += 1
        values = []
        while i < len(tokens):
            if tokens[i].type == TokenType.INTEGER:
                values.append(int(tokens[i].value))
            elif tokens[i].type == TokenType.STRING:
                values.append(tokens[i].value)
            elif tokens[i].type == TokenType.KEYWORD and tokens[i].value == "TRUE":
                values.append(True)
            elif tokens[i].type == TokenType.KEYWORD and tokens[i].value == "FALSE":
                values.append(False)
            elif tokens[i].type == TokenType.KEYWORD and tokens[i].value == "NULL":
                values.append(None)
            else:
                raise SQLSyntaxError("Expected literal value")
            i += 1
            if i >= len(tokens) or tokens[i].value != ")":
                raise SQLSyntaxError("Expected ',' or ')' after value")
            i += 1
            if i >= len(tokens) or tokens[i].value != ";" and tokens[i].type != TokenType.EOF:
                raise SQLSyntaxError("Trailing tokens after INSERT statement")
        return InsertStmt(table_name, tuple(columns) if columns else None, tuple(values))

    def _parse_select(tokens: list[Token]) -> SelectStmt:
        if len(tokens) < 5 or tokens[0].value != "SELECT":
            raise SQLSyntaxError("Malformed SELECT statement")
        i = 1
        columns = []
        if tokens[i].value == "*":
            columns = None
            i += 1
        else:
            while i < len(tokens):
                if tokens[i].type != TokenType.IDENTIFIER:
                    raise SQLSyntaxError("Expected column name")
                columns.append(tokens[i].value)
                i += 1
                if i >= len(tokens) or tokens[i].value != ",":
                    break
                i += 1
        if tokens[i].value != "FROM":
            raise SQLSyntaxError("Expected 'FROM' after column list")
        i += 1
        if tokens[i].type != TokenType.IDENTIFIER:
            raise SQLSyntaxError("Expected table name after 'FROM'")
        table_name = tokens[i].value
        i += 1
        where = None
        if i < len(tokens) and tokens[i].value == "WHERE":
            i += 1
            where = parse_expression(tokens[i:])
            i += len(where.tokens)
        if i != len(tokens) - 1:
            raise SQLSyntaxError("Trailing tokens after SELECT statement")
        return SelectStmt(table_name, tuple(columns) if columns else None, where)

    def _parse_delete(tokens: list[Token]) -> DeleteStmt:
        if len(tokens) < 4 or tokens[0].value != "DELETE" or tokens[1].value != "FROM":
            raise SQLSyntaxError("Malformed DELETE statement")
        table_name = tokens[2].value
        i = 3
        where = None
        if i < len(tokens) and tokens[i].value == "WHERE":
            i += 1
            where = parse_expression(tokens[i:])
            i += len(where.tokens)
        if i != len(tokens) - 1:
            raise SQLSyntaxError("Trailing tokens after DELETE statement")
        return DeleteStmt(table_name, where)

    stmt = _parse_statement(tokens)
    if tokens[-1].value != ";":
        if tokens[-1].type != TokenType.EOF:
            raise SQLSyntaxError("Expected ';' or EOF after statement")
    return stmt


def parse_script(tokens: list[Token]) -> list[Statement]:
    """Parse zero or more ';'-separated statements up to EOF.

    Empty statements (consecutive ';' or a trailing ';') are skipped; an
    empty token stream (just EOF) yields ``[]``.

    Raises:
        SQLSyntaxError: if any statement is malformed.
    """
    statements = []
    i = 0
    while i < len(tokens) - 1:
        if tokens[i].value == ";":
            i += 1
            continue
        j = i
        while j < len(tokens) - 1 and tokens[j].value != ";":
            j += 1
        statement_tokens = tokens[i:j+1]
        if statement_tokens[-1].type == TokenType.EOF:
            statement_tokens = statement_tokens[:-1]
        if statement_tokens:
            statements.append(parse(statement_tokens))
        i = j + 1
    return statements


def parse_expression(tokens: list[Token]) -> Expr:
    """Parse a single WHERE-style expression that must consume every token
    up to EOF.

    Raises:
        SQLSyntaxError: if the tokens do not form exactly one expression.
    """
    def _parse_primary(tokens: list[Token]) -> Expr:
        if not tokens:
            raise SQLSyntaxError("Unexpected EOF")
        token = tokens[0]
        if token.type == TokenType.INTEGER:
            return Literal(int(token.value))
        elif token.type == TokenType.STRING:
            return Literal(token.value)
        elif token.type == TokenType.KEYWORD and token.value == "TRUE":
            return Literal(True)
        elif token.type == TokenType.KEYWORD and token.value == "FALSE":
            return Literal(False)
        elif token.type == TokenType.KEYWORD and token.value == "NULL":
            return Literal(None)
        elif token.type == TokenType.IDENTIFIER:
            return ColumnRef(token.value)
        elif token.type == TokenType.OPERATOR and token.value == "(":
            expr, pos = _parse_expr(tokens[1:])
            if pos >= len(tokens) - 1 or tokens[pos+1].value != ")":
                raise SQLSyntaxError("Expected ')' after expression")
            return expr
        else:
            raise SQLSyntaxError(f"Unexpected token: {token.value}")

    def _parse_predicate(tokens: list[Token]) -> Expr:
        primary, pos = _parse_primary(tokens)
        if pos >= len(tokens) - 1:
            return primary
        next_token = tokens[pos]
        if next_token.type == TokenType.OPERATOR and next_token.value in COMPARISON_OPS:
            right, _ = _parse_primary(tokens[pos+1:])
            return Comparison(next_token.value, primary, right)
        elif next_token.type == TokenType.KEYWORD and next_token.value == "IS":
            if pos + 1 >= len(tokens) - 1:
                raise SQLSyntaxError("Expected NULL or NOT NULL after IS")
            if tokens[pos+1].type == TokenType.KEYWORD and tokens[pos+1].value == "NULL":
                return IsNull(primary, False)
            elif tokens[pos+1].type == TokenType.KEYWORD and tokens[pos+1].value == "NOT":
                if pos + 2 >= len(tokens) - 1 or tokens[pos+2].type != TokenType.KEYWORD or tokens[pos+2].value != "NULL":
                    raise SQLSyntaxError("Expected NULL after NOT")
                return IsNull(primary, True)
            else:
                raise SQLSyntaxError("Expected NULL or NOT NULL after IS")
        else:
            return primary

    def _parse_not_expr(tokens: list[Token]) -> Expr:
        if not tokens:
            raise SQLSyntaxError("Unexpected EOF")
        if tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NOT":
            operand, pos = _parse_not_expr(tokens[1:])
            return Not(operand)
        else:
            return _parse_predicate(tokens)

    def _parse_and_expr(tokens: list[Token]) -> Expr:
        left, pos = _parse_not_expr(tokens)
        if pos >= len(tokens) - 1 or tokens[pos].type != TokenType.KEYWORD or tokens[pos].value != "AND":
            return left
        right, _ = _parse_and_expr(tokens[pos+1:])
        return And(left, right)

    def _parse_or_expr(tokens: list[Token]) -> Expr:
        left, pos = _parse_and_expr(tokens)
        if pos >= len(tokens) - 1 or tokens[pos].type != TokenType.KEYWORD or tokens[pos].value != "OR":
            return left
        right, _ = _parse_or_expr(tokens[pos+1:])
        return Or(left, right)

    def _parse_expr(tokens: list[Token]) -> tuple[Expr, int]:
        expr = _parse_or_expr(tokens)
        if len(tokens) - 1 > pos and tokens[pos+1].type != TokenType.EOF:
            raise SQLSyntaxError("Trailing tokens after expression")
        return expr, pos

    expr, pos = _parse_expr(tokens)
    if pos != len(tokens) - 1:
        raise SQLSyntaxError("Trailing tokens after expression")
    return expr

