        primary, pos = _parse_primary(tokens)
        if pos >= len(tokens) - 1:
            return primary, pos
        next_token = tokens[pos]
        if next_token.type == TokenType.OPERATOR and next_token.value in COMPARISON_OPS:
            right, right_pos = _parse_primary(tokens[pos+1:])
            return Comparison(next_token.value, primary, right), pos + 1 + right_pos
        elif next_token.type == TokenType.KEYWORD and next_token.value == "IS":
            if pos + 1 >= len(tokens) - 1:
                raise SQLSyntaxError("Expected NULL or NOT NULL after IS")
            if tokens[pos+1].type == TokenType.KEYWORD and tokens[pos+1].value == "NULL":
                return IsNull(primary, False), pos + 2
            elif tokens[pos+1].type == TokenType.KEYWORD and tokens[pos+1].value == "NOT":
                if pos + 2 >= len(tokens) - 1 or tokens[pos+2].type != TokenType.KEYWORD or tokens[pos+2].value != "NULL":
                    raise SQLSyntaxError("Expected NULL after NOT")
                return IsNull(primary, True), pos + 3
            else:
                raise SQLSyntaxError("Expected NULL or NOT NULL after IS")
        else:
            return primary, pos

