        if pos >= len(tokens) - 1 or tokens[pos].type != TokenType.KEYWORD or tokens[pos].value != "OR":
            return left, pos
        right, right_pos = _parse_or_expr(tokens[pos+1:])
        return Or(left, right), pos + 1 + right_pos

