        expr, pos = _parse_or_expr(tokens)
        if pos != len(tokens) - 1:
            raise SQLSyntaxError("Trailing tokens after expression")
        return expr, pos

    expr, pos = _parse_expr(tokens)
    if pos != len(tokens) - 1:
        raise SQLSyntaxError("Trailing tokens after expression")
    return expr

